class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def tree_node(values):
    if not values:
        return None
    nodes = [None if value is None else TreeNode(value) for value in values]
    for i, node in enumerate(nodes):
        if node is None:
            continue
        left = 2 * i + 1
        right = 2 * i + 2
        if left < len(nodes):
            node.left = nodes[left]
        if right < len(nodes):
            node.right = nodes[right]
    return nodes[0]


def check(candidate):
    assert candidate(root = tree_node([1, 2, 3])) == 6
    assert candidate(root = tree_node([-10, 9, 20, None, None, 15, 7])) == 42
    assert candidate(root = tree_node([-3])) == -3
    assert candidate(root = tree_node([2, -1])) == 2
    assert candidate(root = tree_node([5, -2, -1, -3, 6])) == 9
    assert candidate(root = tree_node([1, 2, 3, 4, 5])) == 11
